{"data":[{"after":0,"element":{"type":"equation","id":"eq:energy","latex":"\begin{aligned} E(u) &= \frac{1}{2}\sum_{i,j in I} K_{ij}\left(u_j-u_i\right)^2 \end{aligned}","numbered":true,"number":"1"}},{"after":0,"element":{"type":"equation","id":"eq:kernel","latex":"\begin{aligned} K_{ij} &= \exp\left(-\frac{\langle r_{ij},n_i\rangle^2}{lambda^2}\right)\frac{1}{\left(1+\lvert r_{ij}\rvert\right)^rho} \end{aligned}","numbered":true,"number":"2"}},{"after":3,"element":{"type":"equation","id":"eq:vector","latex":"\begin{aligned} r_{ij} &= x_j-x_i, \quad n_i = \frac{a_i}{\sqrt{\langle a_i,a_i\rangle}} \end{aligned}","numbered":true,"number":"3"}},{"after":4,"element":{"type":"equation","id":"eq:local","latex":"\begin{aligned} W_{ij}(u) &= \frac{1}{2}K_{ij}\langle u_j-u_i,u_j-u_i\rangle \end{aligned}","numbered":true,"number":"4"}},{"after":4,"element":{"type":"equation","id":"eq:total","latex":"\begin{aligned} E_{lambda,rho}(u) &= \sum_{i,j in I} W_{ij}(u) \end{aligned}","numbered":true,"number":"5"}},{"after":6,"element":{"type":"equation","id":"eq:minimizer","latex":"\begin{aligned} E_{lambda,rho}(u_*) &= \min_{u in U} E_{lambda,rho}(u) \end{aligned}","numbered":true,"number":"6"}},{"after":6,"element":{"type":"equation","id":"eq:stability","latex":"\begin{aligned} E_{lambda,rho}(u)-E_{lambda,rho}(u_*) &\geq gamma\langle u-u_*,u-u_*\rangle \end{aligned}","numbered":true,"number":"7"}},{"after":8,"element":{"type":"equation","id":"eq:series","latex":"\begin{aligned} \sum_{m=1}^{infty}m^{-rho} &\leq 1+\int_1^{infty}t^{-rho} dt \end{aligned}","numbered":true,"number":"8"}},{"after":8,"element":{"type":"equation","id":"eq:lipschitz","latex":"\begin{aligned} \left|E_{lambda,rho}(u)-E_{lambda,rho}(v)\right| &\leq Lambda\langle u-v,u-v\rangle^{1/2} \end{aligned}","numbered":true,"number":"9"}},{"after":10,"element":{"type":"code","id":"code:iteration","language":"python","caption":"Thuật toán lặp tìm trạng thái năng lượng thấp","content":"for step in range(max_step):
